  jsonb_build_object('heading','Investigue sem entregar a resposta','content',jsonb_build_array('Separe pergunta, hipótese, procedimento, observação e conclusão.','Compare uma variável por vez e ensine a citar dados; hipótese diferente do resultado não é erro.')),
