  jsonb_build_object('title','2. Observar e comparar','instruction','Siga o procedimento seguro e registre o que aconteceu.','activity',guided,'support','Tabela antes-durante-depois e modelagem do professor.'),
  jsonb_build_object('title','3. Concluir e aplicar','instruction','Responda à pergunta usando dados e aplique a ideia em novo caso.','activity',independent,'support','Resposta oral, apontada, tabelada, desenhada, fotografada, digitada ou escrita.')
 ),
 jsonb_build_array(jsonb_build_object('page',1,'answer','Hipótese associada a uma pista.'),jsonb_build_object('page',2,'answer','Observação e comparação coerentes.'),jsonb_build_object('page',3,'answer',answer,'teacher_note','Registre evidência citada, apoio eficaz e próximo passo.')),
 jsonb_build_object('response_modes',jsonb_build_array('oral','pointing','table','drawing','photo','typing','writing'),'routine','adjustable','one_instruction_at_a_time',true,'read_aloud',true,'large_text',true,'visual_schedule',true,'planned_pause',true,'sensory_exit',true,'low_distraction',true,'hands_on',true,'safety_screened',true,'adult_supervision',true,'print','grayscale-safe'),
